// A person's hovercard, read from the store (the person is already in it).
import { useLazyLoadQuery, graphql } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import UIAvatar from "UIAvatar.react";
import UIText from "UIText.react";
import UIButton from "UIButton.react";
import { UIRow, UIColumn } from "UIStack.react";

const styles = stylex.create({
  card: { position: "fixed", zIndex: 40, width: 360, padding: 16, borderRadius: radii.lg, backgroundColor: colors.popoverBackground, boxShadow: elevation.e4 },
});

export default function ProfileHovercard({ actorId, rect }) {
  const data = useLazyLoadQuery(
    graphql`
      query ProfileHovercardQuery($id: ID!) {
        node(id: $id) {
          ... on User {
            name
            profile_picture(size: 80) {
              uri
            }
            mutual_friends {
              text
            }
          }
          ... on Page {
            name
            category_name
            profile_picture(size: 80) {
              uri
            }
          }
        }
      }
    `,
    { id: actorId },
    { fetchPolicy: "store-only" },
  );
  const node = data.node;
  return (
    <div role="dialog" aria-label="Profile preview" style={{ top: rect.bottom + 8, left: rect.left }} {...stylex.props(styles.card)}>
      <UIRow gap={12}>
        <UIAvatar src={node?.profile_picture?.uri} size={80} />
        <UIColumn gap={4}>
          <UIText type="headline3">{node?.name}</UIText>
          <UIText type="meta" color="secondary">
            {node?.mutual_friends?.text ?? node?.category_name}
          </UIText>
        </UIColumn>
      </UIRow>
      <UIRow gap={8}>
        <UIButton label="Message" use="primary" grow />
        <UIButton label="Profile" grow />
      </UIRow>
    </div>
  );
}
